create extension if not exists pgcrypto with schema extensions;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,nickname text not null check(char_length(btrim(nickname)) between 1 and 30),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.bands(id uuid primary key default gen_random_uuid(),name text not null check(char_length(btrim(name)) between 2 and 40),leader_user_id uuid not null references auth.users(id),timezone text not null default 'Asia/Seoul' check(timezone='Asia/Seoul'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.band_members(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,part_key text not null check(char_length(part_key) between 1 and 30),part_label text not null check(char_length(btrim(part_label)) between 1 and 30),skill smallint not null default 3 check(skill between 1 and 5),role text not null default 'member' check(role in ('leader','member')),status text not null default 'active' check(status in ('active','left')),joined_at timestamptz not null default now(),left_at timestamptz,unique(id,band_id));
create unique index band_members_active_user on public.band_members(user_id) where status='active';
create unique index band_members_one_leader on public.band_members(band_id) where status='active' and role='leader';
create table public.band_invites(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,token_hash bytea not null unique,created_by uuid not null references auth.users(id),expires_at timestamptz not null,used_at timestamptz,used_by uuid references auth.users(id),cancelled_at timestamptz,created_at timestamptz not null default now());
create table public.planning_rounds(id uuid primary key default gen_random_uuid(),band_id uuid not null references public.bands(id) on delete cascade,start_date date not null,end_date date not null,status text not null default 'collecting' check(status in ('collecting','ready','invalidated','closed')),version bigint not null default 0 check(version>=0),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(end_date=start_date+59),unique(id,band_id));
create unique index planning_rounds_one_current on public.planning_rounds(band_id) where status in ('collecting','ready');
create table public.round_participants(round_id uuid not null references public.planning_rounds(id) on delete cascade,member_id uuid not null,user_id_snapshot uuid not null,nickname_snapshot text not null,part_key_snapshot text not null,part_label_snapshot text not null,primary key(round_id,member_id),unique(round_id,user_id_snapshot));
create table public.round_submissions(round_id uuid not null,member_id uuid not null,status text not null default 'pending' check(status in ('pending','submitted','none')),submitted_at timestamptz,primary key(round_id,member_id),foreign key(round_id,member_id) references public.round_participants(round_id,member_id) on delete cascade,check((status='pending' and submitted_at is null) or (status<>'pending' and submitted_at is not null)));
create table public.unavailable_dates(band_id uuid not null references public.bands(id) on delete cascade,member_id uuid not null references public.band_members(id) on delete cascade,unavailable_date date not null,reason text not null check(char_length(btrim(reason)) between 1 and 200),updated_at timestamptz not null default now(),primary key(band_id,member_id,unavailable_date));
create table public.songs(id bigint generated always as identity primary key,band_id uuid not null references public.bands(id) on delete cascade,title text not null check(char_length(btrim(title)) between 1 and 120),artist text not null check(char_length(btrim(artist)) between 1 and 120),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,band_id));
create table public.song_difficulties(song_id bigint not null references public.songs(id) on delete cascade,part_key text not null check(char_length(part_key) between 1 and 30),difficulty smallint not null check(difficulty between 1 and 5),primary key(song_id,part_key));
create table public.song_votes(round_id uuid not null references public.planning_rounds(id) on delete cascade,song_id bigint not null references public.songs(id) on delete cascade,member_id uuid not null,choice text not null check(choice in ('yes','no')),reason text,updated_at timestamptz not null default now(),primary key(round_id,song_id,member_id),foreign key(round_id,member_id) references public.round_participants(round_id,member_id) on delete cascade,check((choice='no' and char_length(btrim(coalesce(reason,''))) between 1 and 300) or (choice='yes' and reason is null)));
create table public.confirmed_plans(id uuid primary key default gen_random_uuid(),band_id uuid not null unique references public.bands(id) on delete cascade,round_id uuid not null references public.planning_rounds(id),rehearsal_date date not null,starts_at time not null default '20:00',ends_at time not null default '22:00',participant_count integer not null check(participant_count>0),attendee_count integer not null check(attendee_count>0 and attendee_count<=participant_count),confirmed_by uuid not null references auth.users(id),confirmed_at timestamptz not null default now());
create table public.confirmed_plan_members(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.confirmed_plans(id) on delete cascade,source_member_id uuid,nickname_snapshot text not null,part_snapshot text not null,attending boolean not null,reason_snapshot text);
create table public.confirmed_plan_songs(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.confirmed_plans(id) on delete cascade,source_song_id bigint,title_snapshot text not null,artist_snapshot text not null,display_order integer not null check(display_order>0),unique(plan_id,display_order));
create table public.account_deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,requested_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','processing','completed','rejected')),unique(user_id));

create index band_members_band_status on public.band_members(band_id,status);
create index planning_rounds_band_status on public.planning_rounds(band_id,status);
create index round_participants_user on public.round_participants(user_id_snapshot,round_id);
create index round_submissions_round on public.round_submissions(round_id,status);
create index unavailable_dates_member_date on public.unavailable_dates(member_id,unavailable_date);
create index songs_band on public.songs(band_id,id);
create index song_votes_round_song on public.song_votes(round_id,song_id);

create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
begin insert into public.profiles(id,nickname) values(new.id,coalesce(nullif(btrim(new.raw_user_meta_data->>'nickname'),''),left(split_part(new.email,'@',1),30))) on conflict(id) do nothing; return new; end $$;
revoke all on function private.handle_new_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
create or replace function private.is_band_member(p_band uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.band_members m where m.band_id=p_band and m.user_id=(select auth.uid()) and m.status='active') $$;
create or replace function private.is_band_leader(p_band uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.bands b where b.id=p_band and b.leader_user_id=(select auth.uid())) $$;
create or replace function private.can_read_profile(p_user uuid) returns boolean language sql stable security definer set search_path='' as $$ select p_user=(select auth.uid()) or exists(select 1 from public.band_members a join public.band_members b on b.band_id=a.band_id and b.status='active' where a.user_id=(select auth.uid()) and a.status='active' and b.user_id=p_user) $$;
create or replace function private.can_read_round(p_round uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.planning_rounds r join public.band_members m on m.band_id=r.band_id where r.id=p_round and m.user_id=(select auth.uid()) and m.status='active') $$;
create or replace function private.trim_part_label(p_label text) returns text language sql immutable set search_path='' as $$ select btrim(regexp_replace(p_label,'[[:space:]   -     　]+',' ','g')) $$;
create or replace function private.normalize_part_key(p_label text) returns text language sql immutable set search_path='' as $$ select lower(private.trim_part_label(p_label)) $$;
revoke all on function private.is_band_member(uuid),private.is_band_leader(uuid),private.can_read_profile(uuid),private.can_read_round(uuid),private.trim_part_label(text),private.normalize_part_key(text) from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.is_band_member(uuid),private.is_band_leader(uuid),private.can_read_profile(uuid),private.can_read_round(uuid) to authenticated;

do $$ declare t text; begin
  foreach t in array array['profiles','bands','band_members','band_invites','planning_rounds','round_participants','round_submissions','unavailable_dates','songs','song_difficulties','song_votes','confirmed_plans','confirmed_plan_members','confirmed_plan_songs','account_deletion_requests'] loop execute format('alter table public.%I enable row level security',t); end loop;
end $$;
revoke all on all tables in schema public from anon,authenticated;
alter default privileges in schema public revoke all on tables from anon,authenticated;
grant select on public.profiles,public.bands,public.band_members,public.band_invites,public.planning_rounds,public.round_participants,public.round_submissions,public.unavailable_dates,public.songs,public.song_difficulties,public.song_votes,public.confirmed_plans,public.confirmed_plan_members,public.confirmed_plan_songs,public.account_deletion_requests to authenticated;
grant update(nickname) on public.profiles to authenticated;
create policy profile_band_read on public.profiles for select to authenticated using(private.can_read_profile(id));
create policy profile_self_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy bands_member_read on public.bands for select to authenticated using(private.is_band_member(id));
create policy members_band_read on public.band_members for select to authenticated using(private.is_band_member(band_id));
create policy rounds_band_read on public.planning_rounds for select to authenticated using(private.is_band_member(band_id));
create policy participants_band_read on public.round_participants for select to authenticated using(private.can_read_round(round_id));
create policy submissions_band_read on public.round_submissions for select to authenticated using(private.can_read_round(round_id));
create policy unavailable_band_read on public.unavailable_dates for select to authenticated using(private.is_band_member(band_id));
create policy songs_band_read on public.songs for select to authenticated using(private.is_band_member(band_id));
create policy invite_leader_read on public.band_invites for select to authenticated using(private.is_band_leader(band_id));
create policy difficulties_band_read on public.song_difficulties for select to authenticated using(exists(select 1 from public.songs s where s.id=song_id and private.is_band_member(s.band_id)));
create policy votes_round_read on public.song_votes for select to authenticated using(private.can_read_round(round_id));
create policy plans_band_read on public.confirmed_plans for select to authenticated using(private.is_band_member(band_id));
create policy plan_members_read on public.confirmed_plan_members for select to authenticated using(exists(select 1 from public.confirmed_plans p where p.id=plan_id and private.is_band_member(p.band_id)));
create policy plan_songs_read on public.confirmed_plan_songs for select to authenticated using(exists(select 1 from public.confirmed_plans p where p.id=plan_id and private.is_band_member(p.band_id)));
create policy deletion_self_read on public.account_deletion_requests for select to authenticated using(user_id=(select auth.uid()));

create or replace function public.create_band(p_name text,p_part text,p_nickname text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); b uuid; label text:=private.trim_part_label(p_part);
begin
  if u is null then raise exception 'UNAUTHENTICATED'; end if;
  if char_length(btrim(p_name)) not between 2 and 40 or char_length(label) not between 1 and 30 or char_length(btrim(p_nickname)) not between 1 and 30 then raise exception 'INVALID_INPUT'; end if;
  if exists(select 1 from public.band_members where user_id=u and status='active') then raise exception 'ALREADY_IN_BAND'; end if;
  insert into public.profiles(id,nickname) values(u,btrim(p_nickname)) on conflict(id) do update set nickname=excluded.nickname,updated_at=now();
  b:=gen_random_uuid(); insert into public.bands(id,name,leader_user_id) values(b,btrim(p_name),u);
  insert into public.band_members(band_id,user_id,part_key,part_label,role) values(b,u,private.normalize_part_key(label),label,'leader'); return b;
end $$;
create or replace function public.create_invite(p_band uuid) returns table(token text,expires_at timestamptz) language plpgsql security definer set search_path='' as $$
declare raw text:=encode(extensions.gen_random_bytes(32),'hex');
begin if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if; if not private.is_band_leader(p_band) then raise exception 'FORBIDDEN'; end if;
  insert into public.band_invites(band_id,token_hash,created_by,expires_at) values(p_band,extensions.digest(raw,'sha256'),auth.uid(),now()+interval '7 days') returning band_invites.expires_at into expires_at; token:=raw; return next; end $$;
create or replace function public.inspect_invite(p_token text) returns table(band_name text,valid boolean) language sql stable security definer set search_path='' as $$
  select b.name,(i.expires_at>now() and i.used_at is null and i.cancelled_at is null) from public.band_invites i join public.bands b on b.id=i.band_id where i.token_hash=extensions.digest(p_token,'sha256') limit 1 $$;
create or replace function public.redeem_invite(p_token text,p_part text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); i public.band_invites%rowtype; label text:=private.trim_part_label(p_part);
begin if u is null then raise exception 'UNAUTHENTICATED'; end if; if char_length(label) not between 1 and 30 then raise exception 'INVALID_INPUT'; end if;
 if exists(select 1 from public.band_members where user_id=u and status='active') then raise exception 'ALREADY_IN_BAND'; end if;
 select * into i from public.band_invites where token_hash=extensions.digest(p_token,'sha256') for update;
 if not found then raise exception 'INVITE_INVALID'; end if; if i.used_at is not null then raise exception 'INVITE_USED'; end if; if i.cancelled_at is not null or i.expires_at<=now() then raise exception 'INVITE_EXPIRED'; end if;
 insert into public.band_members(band_id,user_id,part_key,part_label) values(i.band_id,u,private.normalize_part_key(label),label); update public.band_invites set used_at=now(),used_by=u where id=i.id; return i.band_id; end $$;
create or replace function public.start_round(p_band uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r uuid; d date:=(now() at time zone 'Asia/Seoul')::date;
begin if not private.is_band_leader(p_band) then raise exception 'FORBIDDEN'; end if; perform 1 from public.bands where id=p_band for update;
 update public.planning_rounds set status='closed' where band_id=p_band and status in ('collecting','ready');
 if not exists(select 1 from public.band_members where band_id=p_band and status='active') then raise exception 'NO_MEMBERS'; end if;
 insert into public.planning_rounds(band_id,start_date,end_date,created_by) values(p_band,d,d+59,u) returning id into r;
 insert into public.round_participants(round_id,member_id,user_id_snapshot,nickname_snapshot,part_key_snapshot,part_label_snapshot) select r,m.id,m.user_id,p.nickname,m.part_key,m.part_label from public.band_members m join public.profiles p on p.id=m.user_id where m.band_id=p_band and m.status='active';
 insert into public.round_submissions(round_id,member_id) select r,member_id from public.round_participants where round_id=r; return r; end $$;
create or replace function public.save_unavailability(p_round uuid,p_dates jsonb,p_ack_outside boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r public.planning_rounds%rowtype; m uuid; x jsonb; dt date; why text; n_inside int;
begin select * into r from public.planning_rounds where id=p_round for update; if not found or r.status not in ('collecting','ready') then raise exception 'ROUND_INVALID'; end if;
 select member_id into m from public.round_participants where round_id=p_round and user_id_snapshot=u; if m is null then raise exception 'FORBIDDEN'; end if;
 if p_dates is null or jsonb_typeof(p_dates)<>'array' or jsonb_array_length(p_dates)>366 then raise exception 'INVALID_INPUT'; end if;
 for x in select value from jsonb_array_elements(p_dates) loop if coalesce(x->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'INVALID_INPUT'; end if; begin dt:=(x->>'date')::date; exception when others then raise exception 'INVALID_INPUT'; end; why:=btrim(coalesce(x->>'reason','')); if dt<(now() at time zone 'Asia/Seoul')::date or char_length(why) not between 1 and 200 then raise exception 'INVALID_INPUT'; end if; end loop;
 if not coalesce(p_ack_outside,false) and exists(select 1 from jsonb_array_elements(p_dates) x where (x->>'date')::date not between r.start_date and r.end_date) then raise exception 'OUTSIDE_ACK_REQUIRED'; end if;
 if exists(select 1 from jsonb_array_elements(p_dates) with ordinality a(v,ord) join jsonb_array_elements(p_dates) with ordinality b(v,ord) on a.ord<b.ord where a.v->>'date'=b.v->>'date' and a.v->>'reason'<>b.v->>'reason') then raise exception 'DUPLICATE_CONFLICT'; end if;
 delete from public.unavailable_dates where member_id=m and band_id=r.band_id and unavailable_date between r.start_date and r.end_date;
 insert into public.unavailable_dates(band_id,member_id,unavailable_date,reason) select r.band_id,m,(x->>'date')::date,btrim(x->>'reason') from jsonb_array_elements(p_dates) x on conflict(band_id,member_id,unavailable_date) do update set reason=excluded.reason,updated_at=now();
 select count(*) into n_inside from jsonb_array_elements(p_dates) x where (x->>'date')::date between r.start_date and r.end_date;
 update public.round_submissions set status=case when n_inside=0 then 'none' else 'submitted' end,submitted_at=now() where round_id=p_round and member_id=m;
 update public.planning_rounds set version=version+1 where id=p_round returning version into r.version;
 return jsonb_build_object('status',case when n_inside=0 then 'none' else 'submitted' end,'version',r.version); end $$;
create or replace function public.cast_vote(p_round uuid,p_song bigint,p_choice text,p_reason text default null) returns bigint language plpgsql security definer set search_path='' as $$
declare r public.planning_rounds%rowtype; m uuid; b uuid;
begin select * into r from public.planning_rounds where id=p_round for update; if not found or r.status not in ('collecting','ready') then raise exception 'ROUND_INVALID'; end if;
 select member_id into m from public.round_participants where round_id=p_round and user_id_snapshot=auth.uid(); select band_id into b from public.songs where id=p_song;
 if m is null or b is distinct from r.band_id then raise exception 'FORBIDDEN'; end if; if p_choice not in ('yes','no') or (p_choice='no' and char_length(btrim(coalesce(p_reason,''))) not between 1 and 300) then raise exception 'INVALID_INPUT'; end if;
 insert into public.song_votes(round_id,song_id,member_id,choice,reason) values(p_round,p_song,m,p_choice,case when p_choice='no' then btrim(p_reason) else null end) on conflict(round_id,song_id,member_id) do update set choice=excluded.choice,reason=excluded.reason,updated_at=now();
 update public.planning_rounds set version=version+1 where id=p_round returning version into r.version; return r.version; end $$;
create or replace function public.add_song(p_band uuid,p_title text,p_artist text) returns bigint language plpgsql security definer set search_path='' as $$ declare id bigint; begin if not private.is_band_leader(p_band) then raise exception 'FORBIDDEN'; end if; perform 1 from public.planning_rounds where band_id=p_band and status in ('collecting','ready') for update; insert into public.songs(band_id,title,artist,created_by) values(p_band,btrim(p_title),btrim(p_artist),auth.uid()) returning songs.id into id; update public.planning_rounds set version=version+1 where band_id=p_band and status in ('collecting','ready'); return id; end $$;
create or replace function public.update_song_difficulty(p_song bigint,p_part text,p_difficulty smallint) returns void language plpgsql security definer set search_path='' as $$ declare b uuid; begin select band_id into b from public.songs where id=p_song; if b is null or not private.is_band_leader(b) then raise exception 'FORBIDDEN'; end if; if p_difficulty not between 1 and 5 then raise exception 'INVALID_INPUT'; end if; perform 1 from public.planning_rounds where band_id=b and status in ('collecting','ready') for update; insert into public.song_difficulties values(p_song,p_part,p_difficulty) on conflict(song_id,part_key) do update set difficulty=excluded.difficulty; update public.planning_rounds set version=version+1 where band_id=b and status in ('collecting','ready'); end $$;
create or replace function public.update_member_skill(p_member uuid,p_skill smallint) returns void language plpgsql security definer set search_path='' as $$ declare b uuid; begin select band_id into b from public.band_members where id=p_member and status='active'; if b is null or not private.is_band_leader(b) then raise exception 'FORBIDDEN'; end if; if p_skill not between 1 and 5 then raise exception 'INVALID_INPUT'; end if; perform 1 from public.planning_rounds where band_id=b and status in ('collecting','ready') for update; update public.band_members set skill=p_skill where id=p_member; update public.planning_rounds set version=version+1 where band_id=b and status in ('collecting','ready'); end $$;
create or replace function public.update_member_part(p_member uuid,p_part text) returns void language plpgsql security definer set search_path='' as $$ declare b uuid; label text:=private.trim_part_label(p_part); begin select band_id into b from public.band_members where id=p_member and status='active'; if b is null or not private.is_band_leader(b) then raise exception 'FORBIDDEN'; end if; if char_length(label) not between 1 and 30 then raise exception 'INVALID_INPUT'; end if; perform 1 from public.planning_rounds where band_id=b and status in ('collecting','ready') for update; update public.planning_rounds set status='invalidated',version=version+1 where band_id=b and status in ('collecting','ready'); update public.band_members set part_label=label,part_key=private.normalize_part_key(label) where id=p_member; end $$;
create or replace function public.transfer_leadership(p_band uuid,p_member uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_band_leader(p_band) then raise exception 'FORBIDDEN'; end if; perform 1 from public.bands where id=p_band for update; if not exists(select 1 from public.band_members where id=p_member and band_id=p_band and status='active') then raise exception 'INVALID_INPUT'; end if; update public.band_members set role='member' where band_id=p_band and role='leader' and status='active'; update public.band_members set role='leader' where id=p_member; update public.bands set leader_user_id=(select user_id from public.band_members where id=p_member),updated_at=now() where id=p_band; end $$;
create or replace function public.remove_member(p_member uuid) returns void language plpgsql security definer set search_path='' as $$ declare b uuid; begin select band_id into b from public.band_members where id=p_member and status='active'; if b is null or not private.is_band_leader(b) or exists(select 1 from public.band_members where id=p_member and role='leader') then raise exception 'FORBIDDEN'; end if; perform 1 from public.planning_rounds where band_id=b and status in ('collecting','ready') for update; update public.planning_rounds set status='invalidated',version=version+1 where band_id=b and status in ('collecting','ready') and exists(select 1 from public.round_participants rp where rp.round_id=planning_rounds.id and rp.member_id=p_member); update public.band_members set status='left',left_at=now() where id=p_member; end $$;
create or replace function public.leave_band() returns void language plpgsql security definer set search_path='' as $$ declare m public.band_members%rowtype; n int; begin select * into m from public.band_members where user_id=auth.uid() and status='active' for update; if not found then raise exception 'NOT_MEMBER'; end if; select count(*) into n from public.band_members where band_id=m.band_id and status='active'; if m.role='leader' and n>1 then raise exception 'TRANSFER_LEADERSHIP_REQUIRED'; end if; if m.role='leader' then delete from public.bands where id=m.band_id; return; end if; perform 1 from public.planning_rounds where band_id=m.band_id and status in ('collecting','ready') for update; update public.planning_rounds set status='invalidated',version=version+1 where band_id=m.band_id and status in ('collecting','ready') and exists(select 1 from public.round_participants rp where rp.round_id=planning_rounds.id and rp.member_id=m.id); update public.band_members set status='left',left_at=now() where id=m.id; end $$;
create or replace function public.confirm_rehearsal_plan(p_round uuid,p_date date,p_song_ids bigint[],p_expected_version bigint,p_ack_partial boolean default false) returns uuid language plpgsql security definer set search_path='' as $$
declare r public.planning_rounds%rowtype; n int; needed int; attend int; plan uuid; today date:=(now() at time zone 'Asia/Seoul')::date; song bigint;
begin select * into r from public.planning_rounds where id=p_round for update; if not found or r.status not in ('collecting','ready') then raise exception 'ROUND_INVALID'; end if; if not private.is_band_leader(r.band_id) then raise exception 'FORBIDDEN'; end if; if p_expected_version is null or r.version<>p_expected_version then raise exception 'ROUND_STALE'; end if;
 if p_date is null or p_date<greatest(today,r.start_date) or p_date>r.end_date then raise exception 'DATE_OUT_OF_RANGE'; end if; if p_song_ids is null or cardinality(p_song_ids)=0 or cardinality(p_song_ids)<>(select count(distinct x) from unnest(p_song_ids) x) then raise exception 'INVALID_INPUT'; end if;
 select count(*) into n from public.round_participants where round_id=p_round; if n=0 or (select count(*) from public.round_submissions where round_id=p_round)<>n or exists(select 1 from public.round_submissions where round_id=p_round and status='pending') then raise exception 'SUBMISSIONS_PENDING'; end if;
 select count(*) into attend from public.round_participants rp where rp.round_id=p_round and not exists(select 1 from public.unavailable_dates d where d.member_id=rp.member_id and d.band_id=r.band_id and d.unavailable_date=p_date); if attend=0 then raise exception 'NO_ATTENDEES'; end if; if attend<n and not coalesce(p_ack_partial,false) then raise exception 'PARTIAL_ACK_REQUIRED'; end if; needed:=(2*n+2)/3;
 foreach song in array p_song_ids loop
   if not exists(select 1 from public.songs where id=song and band_id=r.band_id) or (select count(*) from public.song_votes where round_id=p_round and song_id=song)<>n or (select count(*) from public.song_votes where round_id=p_round and song_id=song and choice='yes')<needed then raise exception 'SONG_NOT_ELIGIBLE'; end if;
   if exists(select 1 from (select distinct part_key_snapshot k from public.round_participants where round_id=p_round) p where not exists(select 1 from public.song_difficulties d where d.song_id=song and d.part_key=p.k)) then raise exception 'SONG_NOT_ELIGIBLE'; end if;
 end loop;
 delete from public.confirmed_plans where band_id=r.band_id; insert into public.confirmed_plans(band_id,round_id,rehearsal_date,participant_count,attendee_count,confirmed_by) values(r.band_id,p_round,p_date,n,attend,auth.uid()) returning id into plan;
 insert into public.confirmed_plan_members(plan_id,source_member_id,nickname_snapshot,part_snapshot,attending,reason_snapshot) select plan,rp.member_id,rp.nickname_snapshot,rp.part_label_snapshot,not exists(select 1 from public.unavailable_dates d where d.band_id=r.band_id and d.member_id=rp.member_id and d.unavailable_date=p_date),(select d.reason from public.unavailable_dates d where d.band_id=r.band_id and d.member_id=rp.member_id and d.unavailable_date=p_date) from public.round_participants rp where rp.round_id=p_round;
 insert into public.confirmed_plan_songs(plan_id,source_song_id,title_snapshot,artist_snapshot,display_order) select plan,s.id,s.title,s.artist,o::int from unnest(p_song_ids) with ordinality x(id,o) join public.songs s on s.id=x.id; return plan; end $$;
create or replace function public.request_account_deletion() returns uuid language plpgsql security definer set search_path='' as $$ declare id uuid; begin if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if; if exists(select 1 from public.bands b where b.leader_user_id=auth.uid() and (select count(*) from public.band_members m where m.band_id=b.id and m.status='active')>1) then raise exception 'TRANSFER_LEADERSHIP_REQUIRED'; end if; insert into public.account_deletion_requests(user_id) values(auth.uid()) on conflict(user_id) do update set requested_at=now(),status='pending' returning account_deletion_requests.id into id; return id; end $$;
create or replace function public.update_my_nickname(p_nickname text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if; if char_length(btrim(p_nickname)) not between 1 and 30 then raise exception 'INVALID_INPUT'; end if; update public.profiles set nickname=btrim(p_nickname),updated_at=now() where id=auth.uid(); end $$;

revoke execute on all functions in schema public from public,anon;
grant execute on function public.create_band(text,text,text),public.create_invite(uuid),public.redeem_invite(text,text),public.start_round(uuid),public.save_unavailability(uuid,jsonb,boolean),public.cast_vote(uuid,bigint,text,text),public.add_song(uuid,text,text),public.update_song_difficulty(bigint,text,smallint),public.update_member_skill(uuid,smallint),public.update_member_part(uuid,text),public.transfer_leadership(uuid,uuid),public.remove_member(uuid),public.leave_band(),public.confirm_rehearsal_plan(uuid,date,bigint[],bigint,boolean),public.request_account_deletion(),public.update_my_nickname(text) to authenticated;
grant execute on function public.inspect_invite(text) to anon,authenticated;
do $$ begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='planning_rounds') then alter publication supabase_realtime add table public.planning_rounds; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='round_submissions') then alter publication supabase_realtime add table public.round_submissions; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='song_votes') then alter publication supabase_realtime add table public.song_votes; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='confirmed_plans') then alter publication supabase_realtime add table public.confirmed_plans; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='unavailable_dates') then alter publication supabase_realtime add table public.unavailable_dates; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='songs') then alter publication supabase_realtime add table public.songs; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='song_difficulties') then alter publication supabase_realtime add table public.song_difficulties; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='unavailable_dates') then alter publication supabase_realtime add table public.unavailable_dates; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='songs') then alter publication supabase_realtime add table public.songs; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='song_difficulties') then alter publication supabase_realtime add table public.song_difficulties; end if;
 end if;
end $$;
